package dev.ocpplab.session

import org.springframework.data.annotation.Id
import org.springframework.data.relational.core.mapping.Table
import java.math.BigDecimal
import java.time.Instant

enum class SessionStatus { OPEN, CLOSED }

@Table("charging_session")
data class ChargingSession(
    /** Generated by the database (SERIAL); null until the row is inserted. */
    @Id val transactionId: Int? = null,
    val chargePointId: String,
    val connectorId: Int,
    val idTag: String,
    val meterStart: Int,
    val meterStop: Int? = null,
    val startedAt: Instant,
    val stoppedAt: Instant? = null,
    val stopReason: String? = null,
    val status: SessionStatus = SessionStatus.OPEN,
)

@Table("meter_value")
data class MeterValue(
    @Id val id: Long? = null,
    val transactionId: Int,
    val timestamp: Instant,
    val valueWh: BigDecimal,
)
